import java.util.Scanner;
public class Main {
   public static void main(String[] args) {
       Scanner scanner = new Scanner(System.in);
       int emotion = scanner.nextInt();
        switch(emotion){
           case 1:
           System.out.print("你很高兴!");
           break;
           case 2:
           System.out.print("你很悲伤!");
           break;
           case 3:
           System.out.print("你很生气!");
           break;
           case 4:
           System.out.print("你很惊讶!");
           break;
           default:
           System.out.print("unknown");
       }
   }
}
